import json
import os
import random

def generate_wildlife_data():
    label_map = {}
    species_db = {}
    used_words = set()
    
    def add_entry(entry):
        key, name, sci, domain, kingdom, cat, status, pop, habitat, diet, behavior, threats, soil, tags_str = entry
        tags = [t.strip() for t in tags_str.split(",") if t.strip()]
        species_db[key] = {
            "key": key, "name": name, "scientificName": sci, "domain": domain,
            "kingdom": kingdom, "category": cat, "status": status,
            "statusClass": status.lower().replace(" ", "-"), "population": pop,
            "habitat": habitat, "diet": diet, "behavior": behavior,
            "threats": threats, "soil": soil, "tags": tags,
            "desc": f"{name} is a {status.lower()} species."
        }
        words = name.lower().split()
        for i, word in enumerate(words):
            if i == 0 and word not in used_words:
                label_map[word] = key
                used_words.add(word)
        if name.lower() not in used_words:
            label_map[name.lower()] = key
            used_words.add(name.lower())
        if sci.lower() not in used_words:
            label_map[sci.lower()] = key
            used_words.add(sci.lower())
    
