    plants = ["Oak", "Pine", "Spruce", "Fir", "Cedar", "Redwood", "Se replanted)firs", "Birch", "Maple", "Willow", "Poplar", "Aspen", "Elm", "Ash", "Beech", "Chestnut", "Walnut", "Hickory", "Pecan", "Mahogany", "Teak", "Rose", "Lily", "Orchid", "Tulip", "Daisy", "Sunflower", "Dandelion", "Cactus", "Agave", "Aloe", "Fern", "Moss", "Lichen", "Algae", "Seaweed", "Kelp", "Phytoplankton"]
