    protists = ["Amoeba", "Paramecium", "Euglena", "Trypanosoma", "Plasmodium", "Toxoplasma", "Giardia", "Entamoeba", "Paramecium", "Stentor", "Vorticella", "Volvox", "Chlamydomonas", "Spirogyra", "Desmid", "Dinoflagellate", "Diatom", "Foraminiferan", "Radiolarian", "Ciliate", "Flagellate", "Sporozoan", "Apicomplexan", "Kinetoplastid", "Euglenoid", "Dinoflagellate"]
    bacteria = ["Escherichia", "Salmonella", "Shigella", "Klebsiella", "Proteus", "Pseudomonas", "Vibrio", "Helicobacter", "Campylobacter", "Bacillus", "Clostridium", "Listeria", "Staphylococcus", "Streptococcus", "Enterococcus", "Neisseria", "Haernophilus", "Bordetella", "Legionella", "Mycobacterium", "Corynebacterium", "Actinomyces", "Nocardia", "Mycoplasma", "Ureaplasma", "Spiroplasma", "Borrelia", "Treponema", "Leptospira", "Rickettsia", "Chlamydia", "Chlamydophila"]
    archaea = ["Methanopyrus", "Methanococcus", "Methanobacterium", "Methanosarcina", "Halobacterium", "Halococcus", "Haloquadratum", "Haloferax", "Thermococcus", "Pyrococcus", "Sulfolobus", "Acidianus", " Metallosphaera", "Picrophilus", "Thermoplasma", "Ferroplasma", "Archaeoglobus", "Ferroglobus", "Nanoarchaeum", "Cenarchaeum", "Nitrosopumilus"]
    viruses = ["Influenza A", "Influenza B", "Influenza C", "Coronavirus", "SARS-CoV-2", "MERS-CoV", "HIV", "HTLV", "Hepatitis B", "Hepatitis C", "Ebola", "Marburg", "Rabies", "Measles", "Mumps", "Rubella", "Poliovirus", "Rhinovirus", "Adenovirus", "Herpes Simplex", "Varicella Zoster", "Epstein-Barr", "Cytomegalovirus", "Poxvirus", "Parvovirus", "Papillomavirus", "Polyomavirus", "Hepadnavirus", "Arenavirus", "Hantavirus", "Filovirus", "Paramyxovirus", "Rhabdovirus", "Orthomyxovirus", "Coronavirus", "Picornavirus", "Calicivirus", "Togavirus", "Flavivirus", "Bunyavirus", "Reovirus", "Astrovirus", "Norovirus", "Rotavirus", "Hepatitis A", "Hepatitis E", "Dengue", "Zika", "West Nile", "Yellow Fever", "Chikungunya"]
    
    all_categories = [
        ("Mammal", "Eukarya", "Animalia", mammals),
        ("Bird", "Eukarya", "Animalia", birds),
        ("Reptile", "Eukarya", "Animalia", reptiles),
        ("Amphibian", "Eukarya", "Animalia", amphibians),
        ("Fish", "Eukarya", "Animalia", fish),
        ("Insect", "Eukarya", "Animalia", insects),
        ("Plant", "Eukarya", "Plantae", plants),
        ("Fungi", "Eukarya", "Fungi", fungi),
        ("Protist", "Eukarya", "Protista", protists),
        ("Bacteria", "Bacteria", "Bacteria", bacteria),
        ("Archaea", "Archaea", "Archaea", archaea),
        ("Virus", "Viruses", "Viruses", viruses),
    ]
    
    # Generate species from lists
    random.seed(42)
    for cat_name, domain, kingdom, names in all_categories:
        for name in names:
            key = f"{name.lower().replace(' ', '_')}_{cat_name.lower()}"
            genus = name.split()[0]
            sci = f"{genus} {name.lower().replace(' ', '')}ius"
            
            status = random.choice(["Least Concern", "Near Threatened", "Vulnerable", "Endangered", "Critically Endangered"])
            pop = random.choice(["Unknown", "100,000", "50,000", "10,000", "1,000", "500", "100"])
            habitats = ["Forests", "Grasslands", "Savannas", "Deserts", "Wetlands", "Mountains", "Coastal", "Tundra", "Rainforests", "Oceans", "Urban"]
            habitat = random.choice(habitats)
            diets = ["Herbivore", "Carnivore", "Omnivore", "Insectivore", "Piscivore", "Frugivore", "Nectarivore", "Detritivore"]
            diet = random.choice(diets)
            soils_list = ["Loamy", "Sandy", "Clay", "Alluvial", "Humus", "Podzol", "Laterite", "Ferralsol", "Regosol", "Chernozem", "Vertisol", "Andosol", "Permafrost", "Lithosol", "Organic"]
            soil = ", ".join(random.sample(soils_list, 3))
            behaviors = [
                "Typically active during daylight hours.", "Nocturnal hunter with excellent senses.",
                "Highly social, living in groups of up to 50.", "Solitary and territorial.",
                "Migrates seasonally over long distances.", "Ambush predator, waits motionless for prey.",
                "Builds complex nests or burrows.", "Excellent climber, spends most of time in trees."
            ]
            behavior = random.choice(behaviors)
            threats_list = ["Habitat loss", "Climate change", "Pollution", "Overfishing", "Deforestation", "Human conflict", "Poaching", "Invasive species"]
            threats = random.choice(threats_list)
            tags = f"{name.lower()},species,{cat_name.lower()},organism"
            
            add_entry([key, name, sci, domain, kingdom, cat_name, status, pop, habitat, f"{diet} - various", behavior, f"{threats}, habitat degradation", soil, tags])
    
    return {"labelToSpecies": label_map, "speciesDB": species_db}

